174	      if (codepoint == 0) {
175	        reason = "contains a null character";
176	      } else if (codepoint == '\n' || codepoint == '\r') {
177	        reason = "contains a newline";
178	      } else if (codepoint == '\t') {
179	        reason = "contains a tab";
180	      }
181	      ExpectInvalidName(validator, "a" + value + "b", reason);
182	    }
183	    // These continuation bytes overlap the C1 byte range, but their decoded
184	    // codepoints are ordinary letters/symbols and must not be rejected.
185	    EXPECT_TRUE(validator.validate(u8"中文€😀").ok());
186	  }
